export const PostApiV1AttachmentsResponse = zod.object({
  "id": zod.string(),
  "fileName": zod.string(),
  "contentType": zod.string().describe('As the uploader’s browser said; files are always downloaded'),
  "size": zod.int().min(postApiV1AttachmentsResponseSizeMin).max(postApiV1AttachmentsResponseSizeMax).describe('Bytes')
})

/**
 * @summary Remove one of your uploads that was not sent
 */
export const deleteApiV1AttachmentsAttachmentIdPathAttachmentIdRegExp = new RegExp('^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$');


export const DeleteApiV1AttachmentsAttachmentIdParams = zod.object({
  "attachmentId": zod.uuid().regex(deleteApiV1AttachmentsAttachmentIdPathAttachmentIdRegExp)
})

export const DeleteApiV1AttachmentsAttachmentIdResponse = zod.void()

/**
 * Always a download, never shown in the page. Files on messages: every member; your unsent uploads: you.
 * @summary Download a file
 */
export const getApiV1AttachmentsAttachmentIdPathAttachmentIdRegExp = new RegExp('^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$');


export const GetApiV1AttachmentsAttachmentIdParams = zod.object({
  "attachmentId": zod.uuid().regex(getApiV1AttachmentsAttachmentIdPathAttachmentIdRegExp)
})

export const GetApiV1AttachmentsAttachmentIdResponse = zod.unknown()

